from pathlib import Path
from collections import Counter
import json, struct, zlib
from wandb.proto import wandb_internal_pb2 as pb
p=next(Path('results/wandb').rglob('*.wandb'))
s=p.read_bytes()
print('FILE',p,'HEADER',struct.unpack('<4sHB',s[:7]))
i=7; parts=[]; records=[]
while i<len(s):
 left=32768-i%32768
 if left<7:
  assert not any(s[i:i+left]); i+=left; continue
 checksum,n,typ=struct.unpack('<IHB',s[i:i+7]); i+=7
 b=s[i:i+n]; i+=n
 assert checksum==zlib.crc32(b,zlib.crc32(bytes([typ])))&0xffffffff
 if typ==1: data=b
 elif typ==2: parts=[b]; continue
 elif typ==3: parts.append(b); continue
 elif typ==4: data=b''.join(parts+[b]); parts=[]
 else: raise ValueError(typ)
 rec=pb.Record(); rec.ParseFromString(data); records.append(rec)
print('RECORDS',len(records),Counter(r.WhichOneof('record_type') for r in records))
configs={}; summaries={}; histories=[]; stats=[]
def key(it):
 return '/'.join(it.nested_key) if it.nested_key else it.key
def val(it):
 try:return json.loads(it.value_json)
 except:return it.value_json
for r in records:
 t=r.WhichOneof('record_type')
 if t=='config':
  configs.update({key(it):val(it) for it in r.config.update})
 elif t=='summary':
  summaries.update({key(it):val(it) for it in r.summary.update})
 elif t=='history': histories.append({key(it):val(it) for it in r.history.item})
 elif t=='stats': stats.append({key(it):val(it) for it in r.stats.item})
 elif t=='run':
  print('RUN',r.run.run_id,'name',r.run.display_name,'project',r.run.project)
  configs.update({key(it):val(it) for it in r.run.config.update})
 elif t=='exit':print('EXIT',r.exit)
print('CONFIG KEYS',sorted(configs))
print('RELEVANT CONFIG',{k:v for k,v in configs.items() if any(x in k.lower() for x in ['eval','generat','accum','batch','loss','step','reward','model','temper','beta','vllm','liger','seed','world','process'])})
print('HISTORY COUNT',len(histories),'KEYS',sorted(set(k for h in histories for k in h)))
for h in histories:
 if any('eval' in k for k in h): print('EVAL HISTORY',h)
print('SUMMARY',summaries)
print('STATS COUNT',len(stats))
for st in stats[:1]+stats[-1:]:print('STATS SAMPLE',st)
